const upsertGrant = `-- name: UpsertGrant :one
INSERT INTO grp_grant (dashboard_id, group_id, account_id, can_edit)
VALUES ($1, $2, $3, $4)
ON CONFLICT (group_id, account_id) DO UPDATE SET can_edit = EXCLUDED.can_edit
RETURNING dashboard_id, group_id, account_id, can_edit, created_at
`

type UpsertGrantParams struct {
	DashboardID uuid.UUID
	GroupID     uuid.UUID
	AccountID   uuid.UUID
	CanEdit     bool
}

func (q *Queries) UpsertGrant(ctx context.Context, arg UpsertGrantParams) (GrpGrant, error) {
	row := q.db.QueryRow(ctx, upsertGrant,
		arg.DashboardID,
		arg.GroupID,
		arg.AccountID,
		arg.CanEdit,
	)
	var i GrpGrant
	err := row.Scan(
		&i.DashboardID,
		&i.GroupID,
		&i.AccountID,
		&i.CanEdit,
		&i.CreatedAt,
	)
	return i, err
}

